pub fn isSpace(cp: u21) bool {
    return switch (cp) {
        0x9...0xD => true,
        0x20 => true,
        0x85 => true,
        0xA0 => true,
        0x1680 => true,
        0x2000...0x200A => true,
        0x2028...0x2029 => true,
        0x202F => true,
        0x205F => true,
        0x3000 => true,
        else => false,
    };
}

pub fn isPunctuation(cp: u21) bool {
    var lo: usize = 0;
    var hi: usize = punctuation.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const range = punctuation[mid];
        if (cp < range.first) hi = mid else if (cp > range.last) lo = mid + 1 else return true;
    }
    return false;
}
